package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.ExpectedTextVO;

class ExpectedTextValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of expected text of observed probe")
  void test_expected_text_value_holder_assign_plain_value() {
    Object holder = new Object();
    ExpectedTextValueHolder<Object> value = new ExpectedTextValueHolder<>(holder);
    Assertions.assertSame(holder, value.expectedText("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getExpectedTextValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getExpectedText().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.expectedTextNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getExpectedTextValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getExpectedText().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of expected text of observed probe")
  void test_expected_text_value_holder_assign_value_object() {
    Object holder = new Object();
    ExpectedTextValueHolder<Object> value = new ExpectedTextValueHolder<>(holder);
    ExpectedTextVO vo = ExpectedTextVO.from("one");
    Assertions.assertFalse(value.getExpectedTextValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.expectedText(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getExpectedTextValue().orElseThrow());
    Assertions.assertSame(holder, value.expectedText(Optional.empty()));
    Assertions.assertFalse(value.getExpectedTextValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.expectedText(Optional.of(vo)));
    Assertions.assertSame(vo, value.getExpectedTextValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of expected text of observed probe against the original")
  void test_expected_text_value_holder_read() {
    Object holder = new Object();
    ExpectedTextValueHolder<Object> value = new ExpectedTextValueHolder<>(holder);
    ExpectedTextVO vo = ExpectedTextVO.from("one");
    ExpectedTextVO other = ExpectedTextVO.from("one");
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getExpectedTextValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readExpectedText(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readExpectedText(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.expectedText(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readExpectedText(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readExpectedText(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of expected text of observed probe")
  void test_expected_text_value_holder_unset() {
    Object holder = new Object();
    ExpectedTextValueHolder<Object> value = new ExpectedTextValueHolder<>(holder);
    ExpectedTextVO vo = ExpectedTextVO.from("one");
    value.expectedText(vo);
    Assertions.assertSame(holder, value.unsetExpectedTextIfMatches("expectedText_other"));
    Assertions.assertTrue(value.getExpectedTextValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetExpectedTextIfMatches("expectedText"));
    Assertions.assertFalse(value.getExpectedTextValue().isPresent(),
        "The field name must clear the value");
    value.expectedText(vo);
    Assertions.assertSame(holder, value.unsetExpectedText());
    Assertions.assertFalse(value.getExpectedTextValue().isPresent(), "Unset must clear the value");
  }
}
